import os,json,subprocess,stat,hashlib
from pathlib import Path
pair_map={
 'fadego':[(Path('/etc/fadego-staging/app.env'),Path('/srv/projects/fadego/private/systemd-env/app.env')),(Path('/etc/fadego-staging/send-closed.env'),Path('/srv/projects/fadego/private/systemd-env/send-closed.env'))],
 'pink-iptv':[(Path('/etc/pink-iptv/backend.env'),Path('/srv/projects/pink-iptv/private/systemd-env/backend.env')),(Path('/etc/pink-iptv/secrets.env'),Path('/srv/projects/pink-iptv/private/systemd-env/secrets.env')),(Path('/etc/pink-iptv/vpn.env'),Path('/srv/projects/pink-iptv/private/systemd-env/vpn.env'))]
}
out={'audit':'final-project-config-cleanup-readonly','files':{},'old_directories':{},'services':{},'active_consumers':[],'project_roots':[],'protected_vault':{'not_accessed':True},'report_errors':[]}
for project,pairs in pair_map.items():
 for src,dst in pairs:
  x={'old_exists':src.is_file() and not src.is_symlink(),'private_exists':dst.is_file() and not dst.is_symlink()}
  if x['old_exists'] and x['private_exists']:
   x['identical']=hashlib.sha256(src.read_bytes()).digest()==hashlib.sha256(dst.read_bytes()).digest()
   x['modes_match']=stat.S_IMODE(src.stat().st_mode)==stat.S_IMODE(dst.stat().st_mode)
   x['owner_uid_match']=src.stat().st_uid==dst.stat().st_uid
   x['private_mode']=oct(stat.S_IMODE(dst.stat().st_mode))
  out['files'][str(src)]={'project':project,'target':str(dst),**x}
for base in ('/etc/fadego-staging','/etc/pink-iptv'):
 p=Path(base)
 out['old_directories'][base]=sorted([{'name':x.name,'kind':'link' if x.is_symlink() else 'dir' if x.is_dir() else 'file' if x.is_file() else 'other'} for x in p.iterdir()],key=lambda v:v['name']) if p.is_dir() else 'absent'
for name in ('ssh','nginx','postgresql@16-main','fadego-staging','pink-iptv-backend','pink-vpn','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads','project-secrets-offsite-backup.timer'):
 r=subprocess.run(['systemctl','is-active',name],capture_output=True,text=True,timeout=8)
 out['services'][name]=r.stdout.strip()
for service in ('fadego-staging','fadego-booking-email','pink-iptv-backend','pink-vpn'):
 r=subprocess.run(['systemctl','cat',service],capture_output=True,text=True,timeout=10)
 out['active_consumers'].append({'unit':service,'unit_present':r.returncode==0,'environment_file_references':[x.strip() for x in r.stdout.splitlines() if x.strip().startswith('EnvironmentFile=')][:8]})
out['project_roots']=sorted(p.name for p in Path('/srv/projects').iterdir() if p.is_dir() and not p.is_symlink())
for name in ('/srv/projects/fadego/tools/fadego-password','/usr/local/sbin/fadego-password','/srv/projects/pink-iptv/vpn/gateway/pink_vpn_052_install.py'):
 p=Path(name)
 out.setdefault('code_paths',{})[name]={'exists':p.is_file(),'type':'link' if p.is_symlink() else 'regular' if p.is_file() else 'missing'}
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
